@pramodbindal this deep copy in its current form is doing a shallow copy. Now that Globalconfig (https://github.com/tektoncd/operator/pull/3078/changes#diff-d6a7ec5137494ce440af1a8dbbc1e38ae53631b24983df6274663f2ff7cc5e1cR45) is a pointer, this issue seems to be evident. Below snippet worked while testing. we could review this further. Thankyou:
```
// DeepCopyInto is a manual deepcopy function to properly handle the GlobalConfig pointer.
// This manual implementation is required because GlobalConfig is an external type from
// vendor/github.com/tektoncd/pruner/pkg/config that does not have its own DeepCopy methods.
// The code generator cannot generate proper deep copy for external types, so we must manually
// deep copy all nested fields including pointers, maps, and slices to prevent shared references
// between the original and copied objects.
func (in *TektonPrunerConfig) DeepCopyInto(out *TektonPrunerConfig) {
	*out = *in
	if in.GlobalConfig != nil {
		in, out := &in.GlobalConfig, &out.GlobalConfig
		*out = new(config.GlobalConfig)
		// Copy the embedded PrunerConfig fields
		(*out).PrunerConfig = (*in).PrunerConfig
		// Deep copy pointer fields in PrunerConfig
		if (*in).HistoryLimit != nil {
			val := *(*in).HistoryLimit
			(*out).HistoryLimit = &val
		}
		if (*in).SuccessfulHistoryLimit != nil {
			val := *(*in).SuccessfulHistoryLimit
			(*out).SuccessfulHistoryLimit = &val
		}
		if (*in).FailedHistoryLimit != nil {
			val := *(*in).FailedHistoryLimit
			(*out).FailedHistoryLimit = &val
		}
		if (*in).TTLSecondsAfterFinished != nil {
			val := *(*in).TTLSecondsAfterFinished
			(*out).TTLSecondsAfterFinished = &val
		}
		if (*in).EnforcedConfigLevel != nil {
			val := *(*in).EnforcedConfigLevel
			(*out).EnforcedConfigLevel = &val
		}
		// Deep copy the Namespaces map
		if (*in).Namespaces != nil {
			(*out).Namespaces = make(map[string]config.NamespaceSpec, len((*in).Namespaces))
			for key, val := range (*in).Namespaces {
				// Deep copy each NamespaceSpec
				newVal := config.NamespaceSpec{}
				newVal.PrunerConfig = val.PrunerConfig
				// Deep copy pointer fields
				if val.HistoryLimit != nil {
					v := *val.HistoryLimit
					newVal.HistoryLimit = &v
				}
				if val.SuccessfulHistoryLimit != nil {
					v := *val.SuccessfulHistoryLimit
					newVal.SuccessfulHistoryLimit = &v
				}
				if val.FailedHistoryLimit != nil {
					v := *val.FailedHistoryLimit
					newVal.FailedHistoryLimit = &v
				}
				if val.TTLSecondsAfterFinished != nil {
					v := *val.TTLSecondsAfterFinished
					newVal.TTLSecondsAfterFinished = &v
				}
				if val.EnforcedConfigLevel != nil {
					v := *val.EnforcedConfigLevel
					newVal.EnforcedConfigLevel = &v
				}
				// Deep copy PipelineRuns and TaskRuns slices. THIS section is not needed but we will check
				if val.PipelineRuns != nil {
					newVal.PipelineRuns = make([]config.ResourceSpec, len(val.PipelineRuns))
					copy(newVal.PipelineRuns, val.PipelineRuns)
				}
				if val.TaskRuns != nil {
					newVal.TaskRuns = make([]config.ResourceSpec, len(val.TaskRuns))
					copy(newVal.TaskRuns, val.TaskRuns)
				}
				(*out).Namespaces[key] = newVal
			}
		}
	}
}
```

